{"cards": [{"node_code": "N_876a352b5148f289", "definition": "研究铁路钢轨的断面形状、材质性能、几何尺寸、制造工艺及在轨道系统中的受力状态与损伤机理的工程技术内容。", "boundary": "本节点聚焦于钢轨本体。边界在于区分“钢轨”与“联接扣件”（连接件归入钢轨联接及扣件）、“钢轨”与“轨道”（整体系统归入轨道）。若涉及钢轨焊接工艺，侧重焊接接头构造与质量归本节点，侧重焊接设备归施工。若涉及钢轨材料研发，侧重材料微观组织归线路工程材料，侧重宏观性能与选型归本节点。", "includes": ["钢轨断面类型（如UIC60、60kg/m）及几何参数", "钢轨材质、热处理工艺及力学性能指标", "钢轨磨耗、裂纹、疲劳损伤机理及探伤技术"], "excludes": ["钢轨与轨枕、道床的连接装置（归入钢轨联接及扣件）", "轨道整体结构布局与几何状态（归入轨道）"], "sibling_distinctions": [{"other_code": "N_963050fc8a384d06", "rule": "区分依据为对象属性：钢轨关注本体材料、断面与损伤；钢轨联接及扣件关注将钢轨固定于轨枕或连接钢轨之间的装置。"}, {"other_code": "N_94632274f58f3bf0", "rule": "区分依据为层级：钢轨是轨道系统的核心承重部件；轨道涵盖钢轨、轨枕、道床等组成的整体结构。"}], "cross_boundary_rule": "若内容涉及“钢轨焊接”，若侧重焊接接头的构造形式、质量验收标准及接头性能，主挂载本节点；若侧重焊接施工工艺流程及设备操作，主挂载线路施工。"}, {"node_code": "N_963050fc8a384d06", "definition": "研究钢轨之间、钢轨与轨枕之间连接与固定装置的结构形式、材料性能、力学行为及安装维护技术的工程技术内容。", "boundary": "本节点聚焦于“联接”与“扣件”两类装置。边界在于区分“联接”（钢轨端部连接，如鱼尾板、焊接接头构造）与“扣件”（钢轨与轨枕连接，如弹条、螺栓、垫板）。若涉及扣件系统整体设计，归本节点；若涉及扣件材料（如橡胶垫板）的纯材料性能，归线路工程材料。", "includes": ["钢轨接头形式（明桥、暗桥、焊接）及接头构造", "有砟/无砟轨道扣件系统（弹条、扣板、螺栓、垫板）", "扣件系统的力学性能、疲劳寿命及安装调整技术"], "excludes": ["钢轨本体材料与断面（归入钢轨）", "轨枕本体结构与材料（归入轨枕）"], "sibling_distinctions": [{"other_code": "N_876a352b5148f289", "rule": "区分依据为功能：钢轨是承重主体；钢轨联接及扣件是连接与固定主体，起传递荷载和保持轨距作用。"}, {"other_code": "N_bd517f04b88754bc", "rule": "区分依据为对象：扣件是连接钢轨与轨枕的中间件；轨枕是支撑钢轨并分散荷载的横向构件。"}], "cross_boundary_rule": "若内容涉及“扣件系统优化”，若侧重扣件各部件的结构改进与配合关系，主挂载本节点；若侧重扣件材料（如高分子材料）的配方与性能，主挂载线路工程材料。"}, {"node_code": "N_ea528fc63b654a25", "definition": "研究铁路道岔的结构组成、几何尺寸、转辙机构、材料性能及在列车通过时的动力学行为与维护技术的工程技术内容。", "boundary": "本节点聚焦于道岔这一特殊轨道结构。边界在于区分“道岔”与“普通轨道”（道岔包含尖轨、辙叉等复杂部件）、“道岔”与“信号”（道岔控制信号归入通信信号，道岔机械结构归本节点）。若涉及道岔转辙机，侧重机械结构归本节点，侧重电气控制归通信信号。", "includes": ["道岔类型（单开、双开、交叉等）及几何参数", "尖轨、辙叉、护轨等关键部件的结构与材料", "道岔转辙机构、锁闭装置及道岔维护技术"], "excludes": ["道岔控制信号电路与联锁逻辑（归入铁路通信、信号）", "普通直线或曲线轨道的构造（归入轨道）"], "sibling_distinctions": [{"other_code": "N_94632274f58f3bf0", "rule": "区分依据为结构复杂度：轨道指常规直线或曲线轨道；道岔指用于线路分支或交叉的特殊轨道结构，包含尖轨、辙叉等。"}, {"other_code": "N_876a352b5148f289", "rule": "区分依据为部件层级：钢轨是基础部件；道岔是由钢轨、轨枕、扣件等组成的特定功能结构单元。"}], "cross_boundary_rule": "若内容涉及“道岔转辙控制”，若侧重转辙机的机械结构、安装尺寸及道岔几何状态，主挂载本节点；若侧重转辙机的电气驱动、控制电路及信号联锁，主挂载铁路通信、信号。"}]}
